def img(name,alt='',lazy=True,cls=''):
 w,h=images[name];return f'<img class="{cls}" style="max-width:100%;height:auto" src="/assets/{name}" width="{w}" height="{h}" alt="{E(alt)}" '+('loading="lazy"' if lazy else 'fetchpriority="high"')+'>'
