def footer():return '<footer><div class="footer-top"><a href="/#apps">Explore all four apps</a><nav aria-label="Legal and support"><a href="/privacy-policy/">Privacy</a><a href="/privacy-policy-history/">Policy history</a><a href="/terms-of-use/">Terms</a><a href="/contact/">Contact</a><a href="/app-ads.txt">App-ads.txt</a></nav></div><div class="trademark-footer">'+footerlegal+'</div></footer>'
def doc(title,desc,path,body,schema=None,noindex=False):
 data=json.dumps(schema or {'@context':'https://schema.org','@type':'WebPage','name':title,'url':C+path},ensure_ascii=False).replace('<','\\u003c')
 csp="default-src 'self';script-src 'self';style-src 'self' 'unsafe-inline';img-src 'self' data:;font-src 'self';connect-src 'self';object-src 'none';base-uri 'none';form-action 'none';frame-src 'none'"
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(title)+'</title><meta name="description" content="'+E(desc)+'"><link rel="canonical" href="'+C+path+'"><link rel="stylesheet" href="/assets/site.css"><meta http-equiv="Content-Security-Policy" content="'+E(csp)+'"><meta name="theme-color" content="#171b16"><meta property="og:type" content="website"><meta property="og:title" content="'+E(title)+'"><meta property="og:description" content="'+E(desc)+'"><meta property="og:url" content="'+C+path+'"><meta property="og:image" content="'+C+'/assets/1478453789-screen-1.webp"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">'+data+'</script>'+('<meta name="robots" content="noindex,follow">' if noindex else '')+'</head><body>'+header()+body+footer()+'</body></html>'
def write(path,title,desc,body,schema=None,noindex=False):
 dest=R/path.strip('/');dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(doc(title,desc,path,body,schema,noindex))
 if not noindex:routes.append(path)
