 schema={'@context':'https://schema.org','@type':'MobileApplication','name':a['trackName'],'url':C+path,'description':g['summary'],'applicationCategory':'GameApplication','operatingSystem':'iOS, Android','publisher':{'@type':'Organization','name':a['sellerName']},'offers':{'@type':'Offer','price':a['price'],'priceCurrency':a['currency'],'url':a['trackViewUrl'],'eligibleRegion':{'@type':'Country','name':'United States'}},'sameAs':[a['trackViewUrl'],g['android']['storeUrl']]}
